"""Solve a common held-out task and export renderer-neutral world-space chains."""
from pathlib import Path
import json, math, sys, torch
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from design_optimization.topology import load_templates
from design_optimization.kinematics import build_designs,deterministic_joint_samples,joint_world_positions
from design_optimization.ik import deterministic_seeds,solve_multistart
from design_optimization.taskspace import quaternion_wxyz_to_matrix,world_to_base
from design_optimization.collision import self_capsule_clearance,table_capsule_clearance
device='cuda' if torch.cuda.is_available() else 'cpu';task='open-box'; samples=json.loads((ROOT/'data/processed/local_pose_benchmark/test_samples.json').read_text());sample=next(x for x in samples if x['task']==task);dense=json.loads((ROOT/'reports/single_arm/dense_search_results.json').read_text())['robots'];profiles=json.loads((ROOT/'reports/single_arm/collision_proxy_profiles.json').read_text())['robots'];templates=load_templates(ROOT/'reports/single_arm/model_audit.json',device=device);anchor_r=torch.tensor(((0.,-1.,0.),(-1.,0.,0.),(0.,0.,-1.)),device=device);p=torch.tensor(sample['relative_position_m'],device=device);quat=torch.tensor(sample['relative_quaternion_wxyz'],device=device);anchor=torch.tensor((.18,-.45,.35),device=device);world=[]
for xyz,r in zip(anchor+p@anchor_r.T,anchor_r@quaternion_wxyz_to_matrix(quat)):t=torch.eye(4,device=device);t[:3,:3]=r;t[:3,3]=xyz;world.append(t)
world=torch.stack(world);output={'task':task,'duration_s':30,'keyframes':len(world),'robots':{}}
for name,t in templates.items():
 rec=dense[name]['per_task'][task]; raw=torch.tensor(rec['scale_raw'],device=device)[None];design=build_designs(t,raw,deterministic_joint_samples(t,2048));a=math.radians(rec['tilt_deg']);c,s=math.cos(a),math.sin(a);base=torch.eye(4,device=device);base[:3,:3]=torch.tensor(((c,0,s),(0,1,0),(-s,0,c)),device=device);base[:3,3]=torch.tensor(rec['base_xyz_m'],device=device);local=world_to_base(world,base);ik=solve_multistart(design,local,deterministic_seeds(t,32),iterations=120);prof=profiles[name];self_c=self_capsule_clearance(design,ik.q,radii=prof['radii_m'],allowed_pairs=prof['allowed_pairs']);table_c=table_capsule_clearance(design,ik.q,base,radii=prof['radii_m']);clear=torch.minimum(self_c,table_c);cost=400*ik.position_error_m+8*ik.orientation_error_rad+1e5*torch.relu(-clear);branch=cost[0].argmin(1);q=ik.q[0,torch.arange(len(world),device=device),branch];points=joint_world_positions(design,q)[0];points=torch.einsum('ij,tkj->tki',base[:3,:3],points)+base[:3,3];safe=ik.success[0,torch.arange(len(world),device=device),branch]&(clear[0,torch.arange(len(world),device=device),branch]>=0);audit_row=json.loads((ROOT/'reports/single_arm/model_audit.json').read_text())['robots'][name];output['robots'][name]={'joint_names':audit_row['joint_names'],'q_rad':q.tolist(),'deltas_m':design.deltas[0].tolist(),'axes':t.axes.tolist(),'q_min_rad':t.q_min.tolist(),'q_max_rad':t.q_max.tolist(),'points_world_m':points.tolist(),'target_world_m':world[:,:3,3].tolist(),'safe':safe.tolist(),'base_xyz_m':rec['base_xyz_m'],'tilt_deg':rec['tilt_deg']};print(name,float(safe.float().mean()),flush=True)
out=ROOT/'videos/single_arm/cache/open_box_chains.json';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(output),encoding='utf-8');print(out)
